starter.css:
.modal { border: 0; border-radius: 12px; padding: 16px 20px; box-shadow: 0 10px 40px rgb(0 0 0 / 0.3); }
div.modal:not([hidden]) { position: fixed; inset: 10% 10% auto; background: #fff; }
.modal::backdrop { background: rgb(20 16 40 / 0.6); }
.modal h2 { margin-block-start: 0; }
.modal input { display: block; margin-block: 4px 12px; font: inherit; }

starter.js:
const modal = document.querySelector('#booking');

document.querySelector('#book').addEventListener('click', () => {
  modal.hidden = false;
});

document.querySelector('#close').addEventListener('click', () => {
  modal.hidden = true;
});

